#!/usr/bin/env python3
"""Write (or check) the CHANGELOG's "Known issues" list from the findings ledger.

The list is one bullet per open row of docs/project/release-findings.md
whose subsystem is not `interop harness`: the Finding cell as the ledger words
it, then the Workaround cell unless it is a dash. It sits between

  <!-- BEGIN GENERATED by scripts/gen/known-issues.sh; do not edit -->
  <!-- END GENERATED by scripts/gen/known-issues.sh -->

at the end of the section in preparation: the first versioned section while
it still holds its `<!-- TODO(release)` marker line, else `[Unreleased]`. Everything
outside the markers is hand-written and never touched.

Usage:  known_issues.py [--root DIR] [--write | --check]
"""
import argparse
import os
import re
import sys

LEDGER = os.path.join("docs", "project", "release-findings.md")
CHANGELOG = "CHANGELOG.md"
BEGIN = "<!-- BEGIN GENERATED by scripts/gen/known-issues.sh; do not edit -->"
END = "<!-- END GENERATED by scripts/gen/known-issues.sh -->"
MARKER = "<!-- TODO(release)"
HIDDEN_SUBSYSTEMS = ("interop harness",)
COLUMNS = ("Finding", "Subsystem", "Fixed in", "Workaround")


class KnownIssuesError(Exception):
    pass


def split_row(line):
    """The cells of a table row; a `|` inside a code span is not a separator."""
    cells, cur, tick = [], [], False
    for ch in line.strip():
        if ch == "`":
            tick = not tick
        if ch == "|" and not tick:
            cells.append("".join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    cells.append("".join(cur).strip())
    return cells[1:-1]  # the row starts and ends with a pipe


def bullets(ledger_text):
    header, rows = None, []
    for line in ledger_text.splitlines():
        if not line.startswith("|"):
            continue
        cells = split_row(line)
        if header is None:
            if "Finding" in cells:
                header = cells
            continue
        if set("".join(cells)) <= set("-: "):
            continue
        if len(cells) != len(header):
            raise KnownIssuesError("ledger row has %d cells, the header %d: %s"
                                   % (len(cells), len(header), line[:80]))
        rows.append(dict(zip(header, cells)))
    if header is None or any(c not in header for c in COLUMNS):
        raise KnownIssuesError("the ledger table needs the columns %s" % ", ".join(COLUMNS))
    out = []
    for r in rows:
        if r["Fixed in"] != "open" or r["Subsystem"] in HIDDEN_SUBSYSTEMS:
            continue
        text = r["Finding"].rstrip(".")
        text += "."
        if r["Workaround"] not in ("", "—", "-"):
            text += " " + r["Workaround"]
        out.append("- " + text)
    return out


def render(items):
    body = "\n".join(items) if items else "No known issues."
    return "%s\n### Known issues\n\n%s\n%s\n" % (BEGIN, body, END)


def section_bounds(text):
    """(start, end) of the section in preparation, or of [Unreleased]."""
    heads = [m for m in re.finditer(r"^## \[([^\]]+)\].*$", text, flags=re.M)]
    pick = None
    for i, m in enumerate(heads):
        if m.group(1) != "Unreleased":
            # The marker is a line of the section's body, under its heading.
            body_end = heads[i + 1].start() if i + 1 < len(heads) else len(text)
            if MARKER in text[m.end():body_end]:
                pick = m
            break
    if pick is None:
        pick = next((m for m in heads if m.group(1) == "Unreleased"), None)
    if pick is None:
        raise KnownIssuesError("CHANGELOG.md has no [Unreleased] section and none in preparation")
    nxt = [m for m in heads if m.start() > pick.start()]
    return pick.start(), (nxt[0].start() if nxt else len(text))


def apply(changelog, ledger_text):
    block = render(bullets(ledger_text))
    start, end = section_bounds(changelog)
    sec = changelog[start:end]
    if BEGIN in sec:
        i, j = sec.index(BEGIN), sec.find(END)
        if j < 0:
            raise KnownIssuesError("the section has a BEGIN marker and no END marker")
        sec = sec[:i] + block + sec[j + len(END) + 1:]
    else:
        m = re.search(r"\n---\s*\n*\Z", sec)
        if m:
            sec = sec[:m.start()].rstrip("\n") + "\n\n" + block + sec[m.start():]
        else:
            sec = sec.rstrip("\n") + "\n\n" + block
    return changelog[:start] + sec + changelog[end:]


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", ".."))
    mode = ap.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = ap.parse_args(argv)
    root = os.path.abspath(args.root)
    with open(os.path.join(root, LEDGER), encoding="utf-8") as f:
        ledger_text = f.read()
    path = os.path.join(root, CHANGELOG)
    with open(path, encoding="utf-8") as f:
        old = f.read()
    try:
        new = apply(old, ledger_text)
    except KnownIssuesError as e:
        print("known-issues: %s" % e, file=sys.stderr)
        sys.exit(1)
    if args.check:
        if new != old:
            print("known-issues: the Known issues block in CHANGELOG.md is stale; "
                  "run scripts/gen/known-issues.sh", file=sys.stderr)
            sys.exit(1)
        print("known-issues: OK")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)
    print("known-issues: wrote the block in CHANGELOG.md")


if __name__ == "__main__":
    main()
